import { events } from '@adobe-commerce/event-bus';
import { state } from '@/wishlist/lib/state';
import { getStoreConfig, getWishlists } from '@/wishlist/api';
import {
  getPersistedWishlistData,
  setPersistedAllWishlistItems,
} from '@/wishlist/lib/persisted-data';
import { Wishlist } from '@/wishlist/data/models';
import {
  DEFAULT_PAGE_SIZE,
  DEFAULT_CURRENT_PAGE,
} from '@/wishlist/api/constants';
import { populateAllWishlistItems } from '@/wishlist/api/populateAllWishlistItems/populateAllWishlistItems';

export interface InitializeWishlistOptions {
  pageSize?: number;
  currentPage?: number;
}

export const initializeWishlist = async (
  options: InitializeWishlistOptions = {}
): Promise<Wishlist | null> => {
  if (state.initializing) return null;

  state.initializing = true;

  // set config
  if (!state.config) {
    state.config = await getStoreConfig();
  }

  const payload = state.authenticated
    ? await getDefaultWishlist(options)
    : await getGuestWishlist();

  events.emit('wishlist/initialized', payload);
  events.emit('wishlist/data', payload);

  state.initializing = false;

  return payload;
};

export async function getDefaultWishlist(
  options: InitializeWishlistOptions = {}
) {
  const { pageSize = DEFAULT_PAGE_SIZE, currentPage = DEFAULT_CURRENT_PAGE } =
    options;
  const wishlists = await getWishlists(pageSize, currentPage);
  const wishlist = wishlists ? wishlists[0] : null;
  if (!wishlist) return null;

  state.wishlistId = wishlist.id;

  setPersistedAllWishlistItems(wishlist.items ?? []);
  populateAllWishlistItems(wishlist.id, wishlist, pageSize).catch(
    console.error
  );

  return wishlist;
}

export async function getGuestWishlist() {
  try {
    const wishlist = getPersistedWishlistData() as Wishlist | null;
    if (wishlist?.items) {
      setPersistedAllWishlistItems(wishlist.items);
    }
    return wishlist;
  } catch (error) {
    console.error(error);
    throw error;
  }
}
